  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Chant, Medieval and Renaissance Music$j$, $j${"readings": [{"title": "Psalm 96 (King James Version)", "url": "/portal/bible/Psalms/96"}], "body": "Historians divide Western music into periods. The Medieval period runs from about the year 500 to about 1400. The Renaissance runs from about 1400 to about 1600. The word Renaissance means rebirth, and it was a time of new learning in art, science and music.\n\nThe music of the early church was chant. Gregorian chant is a single melody sung in Latin without instruments or harmony, in a free rhythm that follows the words. It is named for Pope Gregory I, who led the church from 590 to 604, and tradition links him with the collection of chant, though scholars believe it developed over many generations. Chant was used in monasteries and churches to sing psalms and prayers. Its calm, flowing sound helped worshippers focus on the words.\n\nA monk named Guido of Arezzo, who lived about 990 to 1050, helped singers learn melodies by developing the staff, the set of lines on which notes are written, and a system of syllable names that grew into do, re, mi. Notation made it possible to teach music across distances and pass it down. Later in the Middle Ages, composers began to sing more than one melody at once, which is polyphony, and a school of composers at Notre Dame in Paris developed it around the year 1200.\n\nIn the Renaissance, polyphony flourished. Choirs sang smooth, interwoven vocal lines, often a cappella. Giovanni Pierluigi da Palestrina, who lived about 1525 to 1594, wrote Masses and motets known for clarity, so that the words could be understood. The printing of music in the early 1500s helped spread it. Common instruments included the lute, recorder and early forms of the viol.\n\nYour task: (1) Name the Medieval and Renaissance periods and their dates. (2) Describe Gregorian chant. (3) Explain how notation and polyphony changed music.\n\nFlorida standards: MU.912.H.1, MU.912.O.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.O.1", "script": "Welcome back. Listen, when we sing from a page today, we stand on the shoulders of centuries of musicians. Let us go back to the beginning.\n\nHistorians divide Western music into periods. The Medieval period runs from about 500 to 1400. The Renaissance runs from about 1400 to 1600. Renaissance means rebirth.\n\nNow watch this. The music of the early church was chant. Gregorian chant is one melody sung in Latin, without instruments or harmony, in a free rhythm that follows the words. It is named for Pope Gregory I, though scholars believe it developed over many generations. Its calm sound helped worshippers focus on the words of the psalms and prayers.\n\nLook at notation. A monk named Guido of Arezzo, around the year 1000, helped develop the staff and a system of syllable names that grew into do, re, mi. Writing music down meant it could be taught across distances and passed on. Later, composers began to sing more than one melody at once. That is polyphony.\n\nIn the Renaissance, choirs sang smooth, interwoven lines, often a cappella. Palestrina wrote music known for clarity, so the words could be understood. The printing of music in the early 1500s helped it spread.\n\nYour task is to name the periods and dates, describe chant, and explain notation and polyphony. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Chant, Medieval and Renaissance Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Baroque and Classical Music$j$, $j${"readings": [{"title": "Revelation 19 (King James Version)", "url": "/portal/bible/Revelation/19"}], "body": "The Baroque period runs from about 1600 to 1750. Baroque music is rich and ornate. Composers used a continuo, a bass line played by instruments such as the organ or cello with chords, and they wrote opera, oratorio, concertos and fugues. A fugue is a piece in which a short theme is imitated by several voices or instruments, one after another.\n\nJohann Sebastian Bach, who lived from 1685 to 1750, served as a church musician in Germany. He wrote cantatas, Passions, organ works and many other pieces. He often wrote the letters S D G at the end of his scores, which stand for the Latin Soli Deo Gloria, to God alone be the glory. George Frideric Handel, who lived from 1685 to 1759, was born in Germany and lived much of his life in England. His oratorio Messiah, composed in 1741 and first performed in Dublin in 1742, sets texts largely from the King James Bible, telling of the promise, birth, death and resurrection of Christ. Its Hallelujah chorus draws on Revelation 19:6, and Revelation 19:16 says, King of kings, and Lord of lords.\n\nThe Classical period runs from about 1750 to 1820. Classical music prizes balance, clarity and form. The symphony, a large work for orchestra, and the string quartet took shape. Franz Joseph Haydn, who lived from 1732 to 1809, wrote more than 100 symphonies. Wolfgang Amadeus Mozart, who lived from 1756 to 1791, composed with astonishing speed and variety in his short life. Ludwig van Beethoven, who lived from 1770 to 1827, bridged the Classical and Romantic styles, and he continued to compose even after losing his hearing.\n\nColossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Bach's habit of dedicating his work to God is a model for any worker or artist.\n\nYour task: (1) Name the Baroque and Classical periods and dates. (2) Tell what Soli Deo Gloria means and why Bach used it. (3) Name one major work or composer from each period and describe it.\n\nFlorida standards: MU.912.H.1, MU.912.C.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.C.1", "script": "Welcome back. Listen, today we meet some of the greatest composers who ever lived, and some of them wrote for the glory of God.\n\nThe Baroque period runs from about 1600 to 1750. Baroque music is rich and ornate. Composers wrote opera, oratorio, concertos and fugues. A fugue is a piece in which a short theme is imitated by voice after voice.\n\nNow watch this. Johann Sebastian Bach, 1685 to 1750, was a church musician in Germany. He often wrote the letters S D G at the end of his scores. They stand for Soli Deo Gloria, to God alone be the glory. Colossians 3:23 says, do it heartily, as to the Lord. That is a model for any worker.\n\nGeorge Frideric Handel, 1685 to 1759, wrote the oratorio Messiah in 1741. It was first performed in Dublin in 1742, and its words come largely from the King James Bible. The Hallelujah chorus draws on Revelation 19:6 and 16, King of kings, and Lord of lords.\n\nLook at the Classical period, 1750 to 1820. It prizes balance, clarity and form. The symphony and string quartet took shape. Haydn wrote more than 100 symphonies. Mozart composed with amazing speed and variety. Beethoven bridged Classical and Romantic music, and kept composing even after he lost his hearing.\n\nYour task is to name the periods and dates, explain Soli Deo Gloria, and describe one work from each period. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Baroque and Classical Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Romantic and Modern Music$j$, $j${"readings": [{"title": "1 Thessalonians 5 (King James Version)", "url": "/portal/bible/1Thessalonians/5"}], "body": "The Romantic period runs from about 1820 to 1900. Romantic composers valued feeling, imagination and personal expression. Orchestras grew larger, and music told stories and painted scenes. Johannes Brahms, who lived from 1833 to 1897, wrote A German Requiem, first performed in 1868, using texts from the Bible in German chosen by the composer, rather than the traditional Latin Mass. Pyotr Ilyich Tchaikovsky, who lived from 1840 to 1893, wrote ballets and symphonies. Giuseppe Verdi, who lived from 1813 to 1901, wrote operas. Frederic Chopin wrote music for the piano.\n\nThe twentieth century brought great change and variety. Composers such as Igor Stravinsky, Aaron Copland and George Gershwin explored new rhythms, new harmonies and American folk and jazz sounds. The recording industry, the radio and later the internet allowed music to reach people everywhere. Film and television made use of orchestral music to create mood. The electronic synthesizer and computer opened new tools for composers and performers. Today people can record, mix and share music from a phone.\n\nTechnology changes how music is made and heard, but the questions remain the same. Is the music good? Is it honest? Does it help or harm the people who hear it? Are the words true? Paul wrote in First Thessalonians 5:21, Prove all things; hold fast that which is good. A listener who learns the elements and the history of music can listen with more understanding, and can enjoy a wider range of music while still holding to what is good.\n\nYour task: (1) Name the Romantic period and dates and tell what Romantic composers valued. (2) Describe one way technology has changed music. (3) Explain what First Thessalonians 5:21 teaches a listener.\n\nFlorida standards: MU.912.H.1, MU.912.F.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.F.1", "script": "Welcome back. Listen, the story of music keeps moving. Today we reach the Romantic period and the modern age.\n\nThe Romantic period runs from about 1820 to 1900. Romantic composers valued feeling, imagination and personal expression. Orchestras grew larger, and music told stories and painted scenes. Brahms wrote A German Requiem, first performed in 1868, using Bible texts he chose himself, in German. Tchaikovsky wrote ballets and symphonies. Verdi wrote operas. Chopin wrote for the piano.\n\nNow watch this. The twentieth century brought great change. Stravinsky, Copland and Gershwin explored new rhythms and harmonies and American folk and jazz sounds. Recording, radio and the internet carried music everywhere. Film used orchestras to create mood. Synthesizers and computers gave composers new tools. Today someone can record and share a song from a phone.\n\nLook at what stays the same. Is the music good? Is it honest? Does it help or harm the people who hear it? Are the words true? First Thessalonians 5:21 says, Prove all things; hold fast that which is good.\n\nA listener who knows the elements and the history of music can listen with more understanding and enjoy a wide range of music while holding to what is good.\n\nYour task is to name the Romantic period, explain how technology changed music, and explain First Thessalonians 5:21. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Romantic and Modern Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 The Great Hymn Writers$j$, $j${"readings": [{"title": "Psalm 98 (King James Version)", "url": "/portal/bible/Psalms/98"}], "body": "A hymn is a song of praise to God, usually with several verses sung to one tune. Martin Luther, who lived from 1483 to 1546, led the Protestant Reformation. He believed that all the people should sing, so he wrote hymns in German, the language of the people. His hymn A Mighty Fortress Is Our God, from about 1529, is based on Psalm 46. John Calvin's followers in Geneva sang the psalms in metrical versions that fit simple tunes.\n\nIsaac Watts, who lived from 1674 to 1748, is called the father of English hymnody. He wrote hundreds of hymns including When I Survey the Wondrous Cross and Joy to the World, which was published in 1719 and is based on Psalm 98. Charles Wesley, who lived from 1707 to 1788, wrote thousands of hymns, including Hark! The Herald Angels Sing, and his brother John Wesley led the Methodist movement. John Newton, who lived from 1725 to 1807, was once a slave ship captain who came to faith in Christ and became a minister. His hymn Amazing Grace appeared in a book of Olney Hymns published in 1779. Fanny Crosby, who lived from 1820 to 1915, lost her sight as a baby and wrote thousands of hymn texts.\n\nHymns are valuable because they teach doctrine in memorable form. Singing good hymns can fix Scripture in the mind. Many hymns are in the public domain, which means that anyone may print or sing them without paying. Find a hymnal at a church or library, read the full verses and compare them with Scripture.\n\nPsalm 119:54 says, Thy statutes have been my songs in the house of my pilgrimage.\n\nYour task: (1) Explain why Luther wrote hymns in German. (2) Match three hymn writers to a hymn they wrote. (3) Explain why hymns are valuable for believers.\n\nFlorida standards: MU.912.H.1, MU.912.C.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.C.3", "script": "Welcome back. Listen, some of the songs we love were written hundreds of years ago, and the stories behind them are powerful.\n\nA hymn is a song of praise to God, usually with several verses sung to one tune. Martin Luther, 1483 to 1546, led the Protestant Reformation. He believed all the people should sing, so he wrote hymns in German, the language of the people. A Mighty Fortress Is Our God, from about 1529, is based on Psalm 46.\n\nNow watch this. Isaac Watts, 1674 to 1748, is called the father of English hymnody. He wrote When I Survey the Wondrous Cross and Joy to the World, published in 1719 and based on Psalm 98. Charles Wesley, 1707 to 1788, wrote thousands of hymns including Hark! The Herald Angels Sing. John Newton, 1725 to 1807, was once a slave ship captain who came to faith in Christ and became a minister. His hymn Amazing Grace appeared in Olney Hymns in 1779. Fanny Crosby, 1820 to 1915, lost her sight as a baby and wrote thousands of hymn texts.\n\nLook at why hymns matter. They teach doctrine in a form we can remember. Singing good hymns fixes Scripture in the mind. Many are in the public domain. Find a hymnal, read the full verses and compare them with Scripture.\n\nPsalm 119:54. Thy statutes have been my songs in the house of my pilgrimage.\n\nYour task is to explain why Luther wrote in German, match three writers to their hymns and explain why hymns are valuable. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 The Great Hymn Writers$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: A History of Western Music and Hymns$j$, $j${"prompt": "Write a report of at least 250 words on the history of Western music and hymns. Use complete sentences and label each part. Psalm 119:54 says, Thy statutes have been my songs in the house of my pilgrimage.\n\nPart 1: Name the five main periods of Western music from Medieval to Romantic with approximate dates, and describe the main feature of each.\nPart 2: Describe Gregorian chant, polyphony and the contribution of Guido of Arezzo.\nPart 3: Explain who Bach and Handel were and what Soli Deo Gloria and Messiah teach about faith and work.\nPart 4: Describe three hymn writers, the hymns they wrote, and why hymns help believers.\nPart 5: Choose one piece from one period, listen to it, and describe what you heard using at least five terms from Unit 1. Explain how technology has changed how we hear music.", "rubric": "100 points. Part 1: 20 points. Part 2: 15 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: A History of Western Music and Hymns$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Songs That Last$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells which older hymn or piece of classical music you have heard, or would like to hear, and what you notice about it, (2) explains why some songs last for hundreds of years while others fade, (3) describes how Bach's habit of writing Soli Deo Gloria could shape your own schoolwork or job, and (4) connects your answer to Colossians 3:23, which says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it valuable for young people to learn music from the past? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Songs That Last$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Chant, Medieval and Renaissance Music$j$, $j${"questions": [{"q": "Gregorian chant is:", "options": ["A piano solo", "A loud brass piece", "A single melody sung without instruments or harmony", "A dance"]}, {"q": "The Renaissance period runs from about:", "options": ["1400 to 1600", "1750 to 1820", "500 to 1400", "1900 to 2000"]}, {"q": "Guido of Arezzo is remembered for helping develop:", "options": ["The symphony", "The staff and syllable names", "The piano", "The radio"]}, {"q": "Singing more than one melody at the same time is called:", "options": ["A rest", "A cadence", "Polyphony", "Monophony"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Chant, Medieval and Renaissance Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,1,2}'::int[], array[$j$Chant is unaccompanied and monophonic.$j$,$j$Renaissance means rebirth.$j$,$j$His work grew into notation and do, re, mi.$j$,$j$Polyphony developed in the later Middle Ages.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Chant, Medieval and Renaissance Music$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Baroque and Classical Music$j$, $j${"questions": [{"q": "Soli Deo Gloria means:", "options": ["Play loudly", "A new song", "To God alone be the glory", "The end"]}, {"q": "The oratorio Messiah was composed by:", "options": ["Handel", "Palestrina", "Mozart", "Haydn"]}, {"q": "The Classical period runs from about:", "options": ["1400 to 1600", "1600 to 1750", "1750 to 1820", "1820 to 1900"]}, {"q": "A fugue is a piece in which:", "options": ["A theme is imitated by several voices or instruments", "Only one note is played", "No rhythm is used", "Everyone plays together on one line"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Baroque and Classical Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,0}'::int[], array[$j$Bach often wrote S D G on his scores.$j$,$j$Handel composed Messiah in 1741.$j$,$j$Classical music prizes balance and clarity.$j$,$j$Fugues build on imitation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Baroque and Classical Music$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Romantic and Modern Music$j$, $j${"questions": [{"q": "Romantic composers valued:", "options": ["Silence", "Feeling, imagination and personal expression", "Only strict form", "Only chant"]}, {"q": "Brahms wrote A German Requiem using:", "options": ["Bible texts in German", "Only Latin texts", "Pop lyrics", "No words"]}, {"q": "Which is a technology that changed how people hear music?", "options": ["Recording and radio", "The metronome only", "Candles", "The quill pen"]}, {"q": "First Thessalonians 5:21 tells us to:", "options": ["Prove all things; hold fast that which is good", "Reject new things", "Avoid all music", "Accept everything"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Romantic and Modern Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,0,0}'::int[], array[$j$Romanticism emphasized emotion.$j$,$j$He chose the texts himself from the Bible.$j$,$j$Recording and radio carried music everywhere.$j$,$j$A listener tests what he hears.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Romantic and Modern Music$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: The Great Hymn Writers$j$, $j${"questions": [{"q": "Martin Luther wrote hymns in German so that:", "options": ["They could be sold", "They would be secret", "All the people could sing", "Only priests could sing"]}, {"q": "Who wrote Joy to the World?", "options": ["Fanny Crosby", "Handel", "John Newton", "Isaac Watts"]}, {"q": "Amazing Grace was written by:", "options": ["John Newton", "Brahms", "Charles Wesley", "Martin Luther"]}, {"q": "Fanny Crosby is remembered as a hymn writer who:", "options": ["Was a pope", "Lived in the Baroque era", "Lost her sight as a baby and wrote thousands of texts", "Wrote only instrumental music"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: The Great Hymn Writers$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,2}'::int[], array[$j$He wanted congregations to sing.$j$,$j$Watts based it on Psalm 98 and it was published in 1719.$j$,$j$Newton's hymn appeared in Olney Hymns in 1779.$j$,$j$She lived 1820 to 1915.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: The Great Hymn Writers$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: A History of Western Music and Hymns$j$, $j${"questions": [{"q": "The Medieval period runs from about:", "options": ["1820 to 1900", "1750 to 1820", "500 to 1400", "1400 to 1600"]}, {"q": "Gregorian chant is named for:", "options": ["Pope Gregory I", "Martin Luther", "Beethoven", "Handel"]}, {"q": "The Renaissance composer known for clarity of words was:", "options": ["Verdi", "Brahms", "Palestrina", "Gershwin"]}, {"q": "Bach lived from:", "options": ["1900 to 1990", "1756 to 1791", "1685 to 1750", "1833 to 1897"]}, {"q": "Handel's Messiah was first performed in:", "options": ["Paris in 1900", "Rome in 1500", "Dublin in 1742", "Vienna in 1800"]}, {"q": "Beethoven continued to compose even after he lost his:", "options": ["Instruments", "Hearing", "Sight", "Voice"]}, {"q": "The father of English hymnody is:", "options": ["Mozart", "John Newton", "Verdi", "Isaac Watts"]}, {"q": "A hymn is:", "options": ["A tempo mark", "A type of drum", "A rest", "A song of praise to God, usually with several verses"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: A History of Western Music and Hymns$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,2,2,1,3,3}'::int[], array[$j$The Medieval period covers about nine hundred years.$j$,$j$Tradition links Gregory I with chant.$j$,$j$Palestrina wrote clear, interwoven vocal music.$j$,$j$Bach lived 1685 to 1750.$j$,$j$It was composed in 1741 and first performed in 1742.$j$,$j$He continued to write music while deaf.$j$,$j$Watts wrote hundreds of hymns.$j$,$j$Hymns teach doctrine in a memorable form.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: A History of Western Music and Hymns$j$ on conflict (item_id) do nothing;
